import httpx
import asyncio
from typing import Any
from fastmcp.server import Server


async def create_openapi_mcp_server(
    openapi_spec: dict[str, Any],
    http_client: httpx.AsyncClient,
) -> Server:
    """Generate an MCP server with tools from an OpenAPI 3.0 specification."""
    server = Server("openapi-mcp")

    for path_pattern, path_item in openapi_spec.get("paths", {}).items():
        for method, operation in path_item.items():
            if method not in ["get", "post", "put", "delete", "patch", "head"]:
                continue

            operation_id = operation.get("operationId", f"{method}_{path_pattern.replace('/', '_').strip('_')}")
            parameters = operation.get("parameters", [])

            def make_tool(path: str, http_method: str, params: list) -> Any:
                async def tool_impl(**kwargs) -> Any:
                    url = path
                    query_params = {}
                    headers = {}
                    body = None

                    for param in params:
                        param_name = param.get("name")
                        if param_name not in kwargs:
                            continue

                        param_value = kwargs[param_name]
                        param_location = param.get("in", "query")

                        if param_location == "path":
                            url = url.replace(f"{{{param_name}}}", str(param_value))
                        elif param_location == "query":
                            query_params[param_name] = param_value
                        elif param_location == "header":
                            headers[param_name] = param_value

                    if "body" in kwargs:
                        body = kwargs["body"]

                    response = await http_client.request(
                        method=http_method.upper(),
                        url=url,
                        params=query_params if query_params else None,
                        headers=headers if headers else None,
                        json=body,
                    )

                    return response.json()

                return tool_impl

            tool = make_tool(path_pattern, method, parameters)
            server.add_tool(operation_id, tool)

    return server


async def main():
    # Example usage
    spec: dict[str, Any] = {
        "openapi": "3.0.0",
        "info": {"title": "Example API", "version": "1.0.0"},
        "servers": [{"url": "https://api.example.com"}],
        "paths": {
            "/users/{id}": {
                "get": {
                    "operationId": "getUser",
                    "parameters": [
                        {"name": "id", "in": "path", "required": True, "schema": {"type": "string"}}
                    ],
                    "responses": {"200": {"description": "Success"}},
                }
            },
            "/posts": {
                "post": {
                    "operationId": "createPost",
                    "parameters": [],
                    "requestBody": {"content": {"application/json": {}}},
                    "responses": {"201": {"description": "Created"}},
                }
            },
        },
    }

    async with httpx.AsyncClient(base_url="https://api.example.com") as client:
        server = await create_openapi_mcp_server(spec, client)
        # Server is ready with tools: getUser, createPost
        async with server.run_in_process():
            await asyncio.sleep(float("inf"))


if __name__ == "__main__":
    asyncio.run(main())

